import unicodedata
from typing import Any

def nfc(s: str) -> str:
    return unicodedata.normalize('NFC', s)

def normalize_nombre(raw: str) -> tuple[str, list[str]]:
    return ' '.join(nfc(raw).split()), ['nfc', 'collapse_spaces']

def normalize_email(raw: str) -> tuple[str, list[str]]:
    s = raw.strip().casefold()
    if s.count('@') != 1 or any(ch.isspace() for ch in s):
        raise ValueError('email requiere un @ y cero espacios')
    local, domain = s.split('@')
    if not local or not domain:
        raise ValueError('email requiere local y dominio')
    return s, ['strip', 'casefold']

def normalize_phone(raw: str) -> tuple[str, list[str]]:
    return ''.join(ch for ch in raw if ch.isdigit()), ['digits_only']

def normalize_record(raw: dict[str, Any]) -> dict[str, Any]:
    normalized = {}
    transforms = {}
    review = []
    normalized['nombre'], transforms['nombre'] = normalize_nombre(raw.get('nombre', ''))
    try:
        normalized['email'], transforms['email'] = normalize_email(raw.get('email', ''))
    except ValueError as exc:
        normalized['email'] = None
        transforms['email'] = ['strip', 'casefold', 'review']
        review.append({'field': 'email', 'reason': str(exc)})
    normalized['telefono'], transforms['telefono'] = normalize_phone(raw.get('telefono', ''))
    return {'raw': dict(raw), 'normalized': normalized, 'transforms': transforms, 'review': review}
